var leaf = AssetDatabase.LoadAssetAtPath<Material>("Assets/AthenHill/Art/HeroTree/leaves.mat");
if(!leaf || EditorApplication.isPlaying || EditorApplication.isCompiling) throw new Exception("Inspect ready material first");
var shader = leaf.shader;
var messages = ShaderUtil.GetShaderMessages(shader);
if(messages.Length != 0) throw new Exception("Tree shader has messages");
var editor = UnityEditor.Editor.CreateEditor(leaf) as MaterialEditor;
var custom = editor.customShaderGUI;
if(custom == null || custom.GetType().FullName != "AthenHill.Editor.WardTreeShaderGUI") throw new Exception("Custom material editor did not resolve");
var clone = new Material(leaf);
var keywordsBefore = clone.shaderKeywords.OrderBy(x=>x).ToArray();
custom.ValidateMaterial(clone);
var keywordsAfter = clone.shaderKeywords.OrderBy(x=>x).ToArray();
if(!keywordsBefore.SequenceEqual(keywordsAfter)) throw new Exception("Keyword validation changed existing material mode");
UnityEngine.Object.DestroyImmediate(clone);
UnityEngine.Object.DestroyImmediate(editor);
var before = leaf.GetFloat("_WardIndirectTranslucency");
Undo.RecordObject(leaf, "Tune reviewed leaf ambient transmission");
leaf.SetFloat("_WardIndirectTranslucency", .15f);
EditorUtility.SetDirty(leaf);
AssetDatabase.SaveAssets();
Selection.activeObject=leaf;
EditorApplication.ExecuteMenuItem("Window/General/Inspector");
return new { customEditor="AthenHill.Editor.WardTreeShaderGUI", before=before, after=leaf.GetFloat("_WardIndirectTranslucency"), keywordsStable=true, shaderMessages=messages.Length, sceneDirty=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().isDirty };
